NodeHttpAdapter.prototype.convertRequestBody = function convertRequestBody(reject, config) {
  var state = this._bodyState;
  var data = state.data;
  if (utils.isFormData(data) && utils.isFunction(data.getHeaders)) {
    state.bodyKind = 'form';
    return data;
  }
  if (!data || utils.isStream(data)) {
    if (data) {
      state.bodyKind = 'stream';
    } else {
      state.bodyKind = 'empty';
    }
    return data;
  }
  if (Buffer.isBuffer(data)) {
    state.bodyKind = 'buffer';
    return data;
  }
  if (utils.isArrayBuffer(data)) {
    data = Buffer.from(new Uint8Array(data));
    state.data = data;
    state.bodyKind = 'buffer';
    return data;
  }
  if (utils.isString(data)) {
    data = Buffer.from(data, 'utf-8');
    state.data = data;
    state.bodyKind = 'buffer';
    return data;
  }
  state.bodyKind = 'invalid';
